use crate::border::{BorderStyle, BubbleStyle, CommentStyle};

#[derive(Default, Debug, Clone)]
pub struct Section {
    pub style: BubbleStyle,
    pub comment_style: CommentStyle,
}

impl Section {
    pub fn new(width: usize, padding: usize, border_style: BorderStyle, comment_style: CommentStyle) -> Self {
        Section {
            style: BubbleStyle { width, padding, border_style },
            comment_style,
        }
    }

    pub fn say(&self, writer: &mut impl std::io::Write, content: impl AsRef<str>) -> std::io::Result<()> {
        crate::say_section_with_style(&mut buf, content.as_ref(), &self.style)?;
        let bubble = String::from_utf8(buf).unwrap();
        for line in bubble.lines() {
            write!(writer, "{}{}", self.comment_style.prefix, line)?;
            if let Some(suffix) = self.comment_style.suffix {
                write!(writer, "{}", suffix)?;
            }
            writeln!(writer)?;
        }
        Ok(())
    }

    pub fn style(&self) -> &BubbleStyle {
        &self.style
    }
    pub fn comment_style(&self) -> &CommentStyle {
        &self.comment_style
    }
}

use crate::border::{BorderStyle, BubbleStyle, CommentStyle};

#[derive(Debug, Clone, Default)]
pub struct Section {
    pub style: BubbleStyle,
    pub comment_style: Option<CommentStyle>,
}

impl Section {
    pub fn new(width: usize, padding: usize, border_style: BorderStyle, comment_style: Option<CommentStyle>) -> Self {
        Section {
            style: BubbleStyle { width, padding, border_style },
            comment_style,
        }
    }

    pub fn builder() -> SectionBuilder {
        SectionBuilder::default()
    }

    /// 输出气泡内容，自动加注释前缀/后缀（如果有）
    pub fn say(&self, writer: &mut impl std::io::Write, content: impl AsRef<str>) -> std::io::Result<()> {
        let style = &self.style;
        let max_line_width = style.width - 2 - style.padding * 2;
        let top_border = format!(
            "{}{}{}",
            style.border_style.top_left,
            style.border_style.horizontal.to_string().repeat(style.width - 2),
            style.border_style.top_right
        );
        let mut buf = Vec::new();
        writeln!(&mut buf, "{top_border}")?;

        let mut chars = content.as_ref().chars().peekable();
        loop {
            while chars.peek().is_some() && *chars.peek().unwrap() == '\n' {
                write!(&mut buf, "{}", style.border_style.vertical)?;
                for _ in 0..(style.width - 2) {
                    write!(&mut buf, "{}", style.border_style.vertical)?;
                }
                writeln!(&mut buf, "{}", style.border_style.vertical)?;
                chars.next();
            }
            if chars.peek().is_none() {
                break;
            }
            let mut current = String::new();
            let mut visual = 0;
            while let Some(&ch) = chars.peek() {
                if ch == '\n' {
                    break;
                }
                let ch_width = crate::visual_width_char(ch);
                if visual + ch_width > max_line_width {
                    break;
                }
                visual += ch_width;
                current.push(ch);
                chars.next();
            }
            if chars.peek() == Some(&'\n') {
                chars.next();
            }
            let spaces = max_line_width - visual;
            let left = style.padding + spaces / 2;
            let right = style.padding + (spaces - spaces / 2);
            write!(&mut buf, "{}", style.border_style.vertical)?;
            for _ in 0..left {
                write!(&mut buf, " ")?;
            }
            write!(&mut buf, "{current}")?;
            for _ in 0..right {
                write!(&mut buf, " ")?;
            }
            writeln!(&mut buf, "{}", style.border_style.vertical)?;
        }
        let bottom_border = format!(
            "{}{}{}",
            style.border_style.bottom_left,
            style.border_style.horizontal.to_string().repeat(style.width - 2),
            style.border_style.bottom_right
        );
        writeln!(&mut buf, "{bottom_border}")?;
        // 输出，每行加注释前缀/后缀（如果有）
        let bubble = String::from_utf8(buf).unwrap();
        for line in bubble.lines() {
            if let Some(ref comment) = self.comment_style {
                write!(writer, "{}{}", comment.prefix, line)?;
                if let Some(suffix) = comment.suffix {
                    write!(writer, "{}", suffix)?;
                }
                writeln!(writer)?;
            } else {
                writeln!(writer, "{}", line)?;
            }
        }
        Ok(())
    }

    pub fn style(&self) -> &BubbleStyle {
        &self.style
    }
    pub fn comment_style(&self) -> Option<&CommentStyle> {
        self.comment_style.as_ref()
    }
}

#[derive(Debug, Clone)]
pub struct SectionBuilder {
    width: usize,
    padding: usize,
    border_style: BorderStyle,
    comment_style: Option<CommentStyle>,
}

impl Default for SectionBuilder {
    fn default() -> Self {
        SectionBuilder {
            width: 48,
            padding: 2,
            border_style: BorderStyle::default(),
            comment_style: None,
        }
    }
}

impl SectionBuilder {
    pub fn width(mut self, width: usize) -> Self {
        self.width = width;
        self
    }
    pub fn padding(mut self, padding: usize) -> Self {
        self.padding = padding;
        self
    }
    pub fn border_style(mut self, border_style: BorderStyle) -> Self {
        self.border_style = border_style;
        self
    }
    pub fn comment_style(mut self, comment_style: CommentStyle) -> Self {
        self.comment_style = Some(comment_style);
        self
    }
    pub fn build(self) -> Section {
        Section {
            style: BubbleStyle {
                width: self.width,
                padding: self.padding,
                border_style: self.border_style,
            },
            comment_style: self.comment_style,
        }
    }
}
